        b.Entity<SupplierBill>(e => { e.ToTable("supplier_bills", t => { t.HasCheckConstraint("CK_supplier_bills_dates", "\"DueDate\">=\"BillDate\""); t.HasCheckConstraint("CK_supplier_bills_amounts", "\"Total\">=0 AND \"AmountPaid\">=0 AND \"AmountPaid\"<=\"Total\""); }); e.HasKey(x => x.Id); e.HasAlternateKey(x => new { x.TenantId, x.CompanyId, x.Id }); e.Property(x => x.Number).HasMaxLength(50); e.Property(x => x.SupplierReference).HasMaxLength(100); e.Property(x => x.PurchaseOrderNumber).HasMaxLength(50); e.Property(x => x.SupplierName).HasMaxLength(200); e.Property(x => x.SupplierTaxNumber).HasMaxLength(100); e.Property(x => x.CurrencyCode).HasMaxLength(3); e.Property(x => x.BaseCurrencyCode).HasMaxLength(3); e.Property(x => x.ExchangeRate).HasPrecision(18, 8); e.Property(x => x.Subtotal).HasPrecision(18, 4); e.Property(x => x.DiscountTotal).HasPrecision(18, 4); e.Property(x => x.TaxTotal).HasPrecision(18, 4); e.Property(x => x.Total).HasPrecision(18, 4); e.Property(x => x.AmountPaid).HasPrecision(18, 4); e.Property(x => x.State).HasConversion<string>().HasMaxLength(24); e.Property(x => x.IdempotencyKey).HasMaxLength(100); e.Property(x => x.ConcurrencyStamp).HasMaxLength(32).IsConcurrencyToken(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.Number }).IsUnique(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.PurchaseOrderId }).IsUnique(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.SupplierId, x.SupplierReference }).IsUnique(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.IdempotencyKey }).IsUnique(); e.HasQueryFilter(x => x.TenantId == TenantId && x.CompanyId == CompanyId); });
        b.Entity<SupplierBillLine>(e => { e.ToTable("supplier_bill_lines"); e.HasKey(x => x.Id); e.Property(x => x.ProductSku).HasMaxLength(100); e.Property(x => x.Description).HasMaxLength(500); e.Property(x => x.UnitCode).HasMaxLength(20); e.Property(x => x.Quantity).HasPrecision(18, 4); e.Property(x => x.UnitPrice).HasPrecision(18, 4); e.Property(x => x.DiscountPercent).HasPrecision(9, 4); e.Property(x => x.TaxPercent).HasPrecision(9, 4); e.Property(x => x.Subtotal).HasPrecision(18, 4); e.Property(x => x.DiscountAmount).HasPrecision(18, 4); e.Property(x => x.TaxAmount).HasPrecision(18, 4); e.Property(x => x.Total).HasPrecision(18, 4); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.SupplierBillId, x.Sequence }).IsUnique(); e.HasQueryFilter(x => x.TenantId == TenantId && x.CompanyId == CompanyId); e.HasOne<SupplierBill>().WithMany(x => x.Lines).HasForeignKey(x => new { x.TenantId, x.CompanyId, x.SupplierBillId }).HasPrincipalKey(x => new { x.TenantId, x.CompanyId, x.Id }).OnDelete(DeleteBehavior.Cascade); });
        b.Entity<Payment>(e => { e.ToTable("payments", t => t.HasCheckConstraint("CK_payments_amount", "\"Amount\">0 AND \"ExchangeRate\">0")); e.HasKey(x => x.Id); e.HasAlternateKey(x => new { x.TenantId, x.CompanyId, x.Id }); e.Property(x => x.Number).HasMaxLength(50); e.Property(x => x.Direction).HasConversion<string>().HasMaxLength(24); e.Property(x => x.PartyName).HasMaxLength(200); e.Property(x => x.CurrencyCode).HasMaxLength(3); e.Property(x => x.ExchangeRate).HasPrecision(18, 8); e.Property(x => x.Amount).HasPrecision(18, 4); e.Property(x => x.Reference).HasMaxLength(100); e.Property(x => x.State).HasConversion<string>().HasMaxLength(16); e.Property(x => x.IdempotencyKey).HasMaxLength(100); e.Property(x => x.PostingKey).HasMaxLength(100); e.Property(x => x.ReversalKey).HasMaxLength(100); e.Property(x => x.ConcurrencyStamp).HasMaxLength(32).IsConcurrencyToken(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.Number }).IsUnique(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.IdempotencyKey }).IsUnique(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.PostingKey }).IsUnique().HasFilter("\"PostingKey\" IS NOT NULL"); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.ReversalKey }).IsUnique().HasFilter("\"ReversalKey\" IS NOT NULL"); e.HasQueryFilter(x => x.TenantId == TenantId && x.CompanyId == CompanyId); });
        b.Entity<PaymentAllocation>(e => { e.ToTable("payment_allocations", t => { t.HasCheckConstraint("CK_payment_allocations_amount", "\"Amount\">0"); t.HasCheckConstraint("CK_payment_allocations_target", "(\"CustomerInvoiceId\" IS NOT NULL AND \"SupplierBillId\" IS NULL) OR (\"CustomerInvoiceId\" IS NULL AND \"SupplierBillId\" IS NOT NULL)"); }); e.HasKey(x => x.Id); e.Property(x => x.DocumentNumber).HasMaxLength(50); e.Property(x => x.Amount).HasPrecision(18, 4); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.PaymentId, x.CustomerInvoiceId }).IsUnique().HasFilter("\"CustomerInvoiceId\" IS NOT NULL"); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.PaymentId, x.SupplierBillId }).IsUnique().HasFilter("\"SupplierBillId\" IS NOT NULL"); e.HasQueryFilter(x => x.TenantId == TenantId && x.CompanyId == CompanyId); e.HasOne<Payment>().WithMany(x => x.Allocations).HasForeignKey(x => new { x.TenantId, x.CompanyId, x.PaymentId }).HasPrincipalKey(x => new { x.TenantId, x.CompanyId, x.Id }).OnDelete(DeleteBehavior.Cascade); });
        b.Entity<TaxCode>(e => { e.ToTable("tax_codes", t => t.HasCheckConstraint("CK_tax_codes_rate", "\"Rate\">=0 AND \"Rate\"<=100")); e.HasKey(x => x.Id); e.Property(x => x.Code).HasMaxLength(50); e.Property(x => x.Name).HasMaxLength(200); e.Property(x => x.Rate).HasPrecision(9, 4); e.Property(x => x.ConcurrencyStamp).HasMaxLength(32).IsConcurrencyToken(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.Code }).IsUnique(); e.HasQueryFilter(x => x.TenantId == TenantId && x.CompanyId == CompanyId); });
        b.Entity<CurrencyRate>(e => { e.ToTable("currency_rates", t => t.HasCheckConstraint("CK_currency_rates_rate", "\"Rate\">0")); e.HasKey(x => x.Id); e.Property(x => x.BaseCurrencyCode).HasMaxLength(3); e.Property(x => x.QuoteCurrencyCode).HasMaxLength(3); e.Property(x => x.Rate).HasPrecision(18, 8); e.Property(x => x.ConcurrencyStamp).HasMaxLength(32).IsConcurrencyToken(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.BaseCurrencyCode, x.QuoteCurrencyCode, x.EffectiveDate }).IsUnique(); e.HasQueryFilter(x => x.TenantId == TenantId && x.CompanyId == CompanyId); });
        b.Entity<BankReconciliation>(e => { e.ToTable("bank_reconciliations"); e.HasKey(x => x.Id); e.HasAlternateKey(x => new { x.TenantId, x.CompanyId, x.Id }); e.Property(x => x.Number).HasMaxLength(50); e.Property(x => x.OpeningBalance).HasPrecision(18, 4); e.Property(x => x.ClosingBalance).HasPrecision(18, 4); e.Property(x => x.State).HasConversion<string>().HasMaxLength(16); e.Property(x => x.ConcurrencyStamp).HasMaxLength(32).IsConcurrencyToken(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.Number }).IsUnique(); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.BankAccountId, x.StatementDate }).IsUnique(); e.HasQueryFilter(x => x.TenantId == TenantId && x.CompanyId == CompanyId); });
        b.Entity<BankReconciliationLine>(e => { e.ToTable("bank_reconciliation_lines"); e.HasKey(x => x.Id); e.Property(x => x.JournalEntryNumber).HasMaxLength(50); e.Property(x => x.Amount).HasPrecision(18, 4); e.HasIndex(x => new { x.TenantId, x.CompanyId, x.JournalEntryId }).IsUnique(); e.HasQueryFilter(x => x.TenantId == TenantId && x.CompanyId == CompanyId); e.HasOne<BankReconciliation>().WithMany(x => x.Lines).HasForeignKey(x => new { x.TenantId, x.CompanyId, x.BankReconciliationId }).HasPrincipalKey(x => new { x.TenantId, x.CompanyId, x.Id }).OnDelete(DeleteBehavior.Cascade); });
