    public override Task<int> SaveChangesAsync(bool accept, CancellationToken token = default) { var changed = ChangeTracker.Entries().Where(x => x.State is EntityState.Added or EntityState.Modified or EntityState.Deleted).ToArray(); if (changed.Length > 0) { var t = tenant?.TenantId?.Value ?? throw new InvalidOperationException("An active tenant is required."); var c = company?.CompanyId?.Value ?? throw new InvalidOperationException("An active company is required."); if (changed.Any(x => Scope(x.Entity) != (t, c))) throw new InvalidOperationException("Cross-tenant or cross-company accounting writes are not permitted."); if (changed.Any(x => x.Entity is JournalEntry && x.State != EntityState.Added && x.OriginalValues.GetValue<JournalEntryState>(nameof(JournalEntry.State)) == JournalEntryState.Posted)) throw new InvalidOperationException("Posted journal entries are immutable; create a reversal."); if (changed.Any(x => x.Entity is JournalEntryLine line && x.State != EntityState.Added && JournalEntries.AsNoTracking().Any(header => header.Id == line.JournalEntryId && header.State == JournalEntryState.Posted))) throw new InvalidOperationException("Posted journal entry lines are immutable; create a reversal."); } return base.SaveChangesAsync(accept, token); }
    private static (Guid, Guid) Scope(object x) => x switch { Account v => (v.TenantId, v.CompanyId), FiscalPeriod v => (v.TenantId, v.CompanyId), Journal v => (v.TenantId, v.CompanyId), JournalEntry v => (v.TenantId, v.CompanyId), JournalEntryLine v => (v.TenantId, v.CompanyId), CustomerInvoice v => (v.TenantId, v.CompanyId), CustomerInvoiceLine v => (v.TenantId, v.CompanyId), SupplierBill v => (v.TenantId, v.CompanyId), SupplierBillLine v => (v.TenantId, v.CompanyId), Payment v => (v.TenantId, v.CompanyId), PaymentAllocation v => (v.TenantId, v.CompanyId), TaxCode v => (v.TenantId, v.CompanyId), CurrencyRate v => (v.TenantId, v.CompanyId), BankReconciliation v => (v.TenantId, v.CompanyId), BankReconciliationLine v => (v.TenantId, v.CompanyId), _ => (Guid.Empty, Guid.Empty) };
}
public sealed class AccountingDesignTimeFactory : IDesignTimeDbContextFactory<AccountingDbContext> { public AccountingDbContext CreateDbContext(string[] args) => new(new DbContextOptionsBuilder<AccountingDbContext>().UseNpgsql("Host=localhost;Database=erp_design;Username=erp;Password=design_only").Options); }
